"html": "<footer style=\"position: relative; width: 1440px; background: #F9CBD8; height: 780px; overflow: hidden; color: #3A1210; font-family: 'DotGothic16', 'Osaka-Mono', ui-monospace, monospace; border-top: 2px dashed rgba(94,23,20,0.35);\">\n    <div aria-hidden=\"true\" style=\"position: absolute; left: 220px; top: 420px; width: 1000px; height: 1000px; border-radius: 50%; overflow: hidden; background-image: radial-gradient(circle, #D93A2B 0 47%, transparent 49%); background-size: 12px 12px;\"><div style=\"position: absolute; left: 58%; top: 30%; width: 50%; height: 50%; border-radius: 50%; background-image: radial-gradient(circle, #9E2318 0 62%, transparent 64%); background-size: 12px 12px;\"></div></div>\n    <svg aria-hidden=\"true\" viewBox=\"0 0 120 120\" width=\"100\" height=\"100\" style=\"position: absolute; left: 640px; top: 70px; transform: rotate(14deg);\"><polygon points=\"60,8 74,44 112,46 82,70 92,108 60,86 28,108 38,70 8,46 46,44\" fill=\"#F6EFC4\" stroke=\"#F6EFC4\" stroke-width=\"14\" stroke-linejoin=\"round\"></polygon><polygon points=\"60,8 74,44 112,46 82,70 92,108 60,86 28,108 38,70 8,46 46,44\" fill=\"none\" stroke=\"#E2D38E\" stroke-width=\"3\" stroke-linejoin=\"round\"></polygon><ellipse cx=\"48\" cy=\"42\" rx=\"12\" ry=\"7\" fill=\"#FFFFFF\" transform=\"rotate(-30 48 42)\"></ellipse></svg>\n    <div style=\"position: absolute; left: 120px; top: 90px; width: 640px; display: flex; flex-direction: column; gap: 14px;\">\n      <span style=\"font-size: 14px; letter-spacing: 0.18em; color: #D93A2B;\">LET'S CONNECT</span>\n      <h2 style=\"margin: 0; font-family: 'Dela Gothic One', 'Hiragino Kaku Gothic StdN', sans-serif; font-weight: 400; font-size: 60px; line-height: 1.1; color: #5E1714;\">LET'S CREATE<br>SOMETHING<br>TOGETHER.</h2>\n      <p style=\"margin: 4px 0 0; font-size: 16px; line-height: 1.8;\">お仕事のご相談やご感想など、お気軽にご連絡ください。</p>\n    </div>\n    <a href=\"mailto:yuuna.tatihara@gmail.com\" style=\"position: absolute; left: 140px; top: 470px; display: flex; align-items: center; gap: 16px; padding: 22px 30px 22px 60px; background: #FFF9F4; border-radius: 16px; transform: rotate(-3deg); box-shadow: 0 14px 0 -6px rgba(94,23,20,0.22); text-decoration: none; color: #5E1714;\">\n      <span aria-hidden=\"true\" style=\"position: absolute; left: 22px; top: 50%; width: 18px; height: 18px; margin-top: -9px; border-radius: 50%; background: #F9CBD8; box-shadow: inset 0 0 0 3px #5E1714;\"></span>\n      <span style=\"font-family: 'Dela Gothic One', 'Hiragino Kaku Gothic StdN', sans-serif; font-size: 30px; line-height: 1;\">yuuna.tatihara@gmail.com</span>\n    </a>\n    <nav aria-label=\"フッターメニュー\" style=\"position: absolute; left: 1010px; top: 110px; width: 300px; transform: rotate(3deg); filter: drop-shadow(0 14px 14px rgba(94,23,20,0.22));\">\n      <div style=\"background: #FBF8F2; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 8px), 100.00% calc(100% - 8px), 96.15% 100%, 92.31% calc(100% - 8px), 88.46% 100%, 84.62% calc(100% - 8px), 80.77% 100%, 76.92% calc(100% - 8px), 73.08% 100%, 69.23% calc(100% - 8px), 65.38% 100%, 61.54% calc(100% - 8px), 57.69% 100%, 53.85% calc(100% - 8px), 50.00% 100%, 46.15% calc(100% - 8px), 42.31% 100%, 38.46% calc(100% - 8px), 34.62% 100%, 30.77% calc(100% - 8px), 26.92% 100%, 23.08% calc(100% - 8px), 19.23% 100%, 15.38% calc(100% - 8px), 11.54% 100%, 7.69% calc(100% - 8px), 3.85% 100%, 0.00% calc(100% - 8px)); padding: 26px 28px 40px; display: flex; flex-direction: column; gap: 10px; font-size: 16px;\">\n        <span style=\"text-align: center; font-size: 12px; letter-spacing: 0.3em;\">✣ MENU ✣</span>\n        <span aria-hidden=\"true\" style=\"border-top: 2px dashed rgba(58,18,16,0.45);\"></span>\n        <a href=\"/c\" style=\"display: flex; align-items: baseline; gap: 8px; min-height: 36px; text-decoration: none; color: #3A1210;\"><span>01 ホーム</span><span aria-hidden=\"true\" style=\"flex: 1; border-bottom: 2px dotted rgba(58,18,16,0.4); transform: translateY(-4px);\"></span><span>→</span></a>\n        <a href=\"/c/about\" style=\"display: flex; align-items: baseline; gap: 8px; min-height: 36px; text-decoration: none; color: #3A1210;\"><span>02 私について</span><span aria-hidden=\"true\" style=\"flex: 1; border-bottom: 2px dotted rgba(58,18,16,0.4); transform: translateY(-4px);\"></span><span>→</span></a>\n        <span aria-hidden=\"true\" style=\"border-top: 2px dashed rgba(58,18,16,0.45);\"></span>\n        <span style=\"text-align: center; font-size: 12px; letter-spacing: 0.2em;\">THANK YOU!</span>\n      </div>\n    </nav>\n    <div style=\"position: absolute; left: 0; right: 0; bottom: 0; min-height: 72px; padding: 0 120px; box-sizing: border-box; display: flex; justify-content: space-between; align-items: center; background: #5E1714; color: #F9CBD8; font-size: 14px;\">\n      <span>© 2026 Yuuna Tachihara</span>\n      <a href=\"#top\" style=\"display: inline-flex; align-items: center; min-height: 44px; text-decoration: none; color: #F9CBD8;\">ページの先頭へ ↑</a>\n    </div>\n  </footer>"
